def solve_all_graphs():
    n = 120
    max_n1 = 0

    # Case 1: K_a \cup (n-a)I
    for a in range(n + 1):
        n1 = (a * (a - 1) // 2) * ((n - a) * (n - a - 1) // 2)
        if n1 > max_n1:
            max_n1 = n1

    # Case 2: K_{n1, n2, ..., nk}
    for k in range(2, n + 1):
        m = n // k
        r = n % k
        ns = [m + 1] * r + [m] * (k - r)

        S = 0
        for i in range(k):
            for j in range(i + 1, k):
                S += ns[i] * ns[j]

        n1 = 0
        for i in range(k):
            for j in range(i + 1, k):
                term = ns[i] * ns[j]
                sum_p_q = S
                sum_p_q -= ns[i] * ns[j]
                sum_p_q -= ns[i] * (n - ns[i] - ns[j])
                sum_p_q -= ns[j] * (n - ns[i] - ns[j])
                n1 += term * ( (n - ns[i] - ns[j]) * (n - ns[i] - ns[j] - 1) // 2 - sum_p_q )
        if n1 > max_n1:
            max_n1 = n1

    # Case 3: Star K_{1, m}
    for m in range(n):
        n1 = m * (n - m - 1) * (n - m - 2) // 2
        if n1 > max_n1:
            max_n1 = n1

    # Case 4: Matching m
    for m in range(n // 2 + 1):
        n1 = m * (n - 2 * m) * (n - 2 * m - 1) // 2
        if n1 > max_n1:
            max_n1 = n1

    return max_n1

