    from itertools import product
    def get_partitions(n_rem, min_val):
        if n_rem == 0:
            yield []
            return
        for i in range(min_val, n_rem + 1):
            for p in get_partitions(n_rem - i, i):
                yield [i] + p

    for partition in get_partitions(n, 1):
        k = len(partition)
