                n1 += term
        best_n1 = max(best_n1, n1)

    # Case 3: Star K_{1, m}
    for m in range(n + 1):
        n1 = m * (n - m - 1) * (n - m - 2) // 2
        best_n1 = max(best_n1, n1)

